s=s.replace('49.35','59.35').replace('59.35 or not .65<y<59.35','59.35 or not .65<y<69.35')
s=s.replace("q['ref'] in ['U1','U2'] and min(q['geom'].bounds[2]-q['geom'].bounds[0],q['geom'].bounds[3]-q['geom'].bounds[1])>.6","((q['ref']=='U1' and q['number']=='29') or (q['ref']=='U2' and q['number'] in [str(n) for n in range(88,95)]))")
s=s.replace('supply-ground-fanout-v12','supply-ground-fanout-large-v12').replace('fanout-connected-v12','fanout-connected-large-v12')
(P/'plan-supply-fanout-large-v12.py').write_text(s,encoding='utf8')
s=(P/'repair-supply-fanout-v12.py').read_text().replace('router-v12.py','router-large-v12.py').replace("['rf-routing-v12','usb-routing-retained-v12','usb-rework-v12','supply-ground-fanout-v12']","['critical-large-v12','supply-ground-fanout-large-v12']").replace('supply-ground-fanout-v12','supply-ground-fanout-large-v12').replace('supply-ground-repair-v12','supply-ground-repair-large-v12')
(P/'repair-supply-fanout-large-v12.py').write_text(s,encoding='utf8')
s=(P/'plan-power-routing-v12.py').read_text().replace('router-v12.py','router-large-v12.py').replace("['rf-routing-v12','usb-routing-retained-v12','usb-rework-v12','supply-ground-fanout-v12','supply-ground-repair-v12']","['critical-large-v12','supply-ground-fanout-large-v12','supply-ground-repair-large-v12']")
s=s.replace('box(14.5,40.8,20.8,49.2)','box(16.4,54.8,24,61.5),box(27.3,38.0,35,43.4)')
s=s.replace("for w in [.35,.254]:","for w in [.6,.35,.254]:").replace('power-routing-v12','power-routing-large-v12')
(P/'plan-power-routing-large-v12.py').write_text(s,encoding='utf8')
